const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 1920, height: 1080 },
    recordVideo: {
      dir: '.',
      size: { width: 1920, height: 1080 }
    }
  });

  const page = await context.newPage();
  const htmlPath = path.resolve(__dirname, 'explainer.html');

  console.log('Loading page...');
  await page.goto(`file://${htmlPath}`);

  // 等待动画准备就绪
  await page.waitForFunction(() => window.__ready === true, { timeout: 5000 });
  console.log('Animation ready, recording for 108 seconds...');

  // 录制 108 秒（总时长）
  await page.waitForTimeout(108000);

  console.log('Recording complete, saving video...');
  await context.close();

  // 视频会保存在临时目录，需要移动到当前目录
  const videoPath = await page.video().path();
  const finalPath = path.join(__dirname, 'explainer-raw.webm');

  // playwright 录制的视频在 close 后自动保存
  console.log('Video saved. Converting to MP4...');

  await browser.close();

  console.log('Done!');
})();

